INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q60769179', '1970 Lesotho coup d''état', 'The 1970 Lesotho coup d''état was a self-coup that took place in Lesotho on 30 January 1970, led by Prime Minister Leabua Jonathan. It led to the assumption of dictatorial powers by Prime Minister Jonathan, who held the office since 1965.', 1970, 1, 30, NULL, NULL, NULL, 'day', '30 January 1970', 41, 'https://en.wikipedia.org/wiki/1970_Lesotho_coup_d''%C3%A9tat'),
  ('Q39046971', '1986 Lesotho coup d''état', 'The 1986 Lesotho coup d''état was a military coup that took place in Lesotho on 20 January 1986, led by General Justin Lekhanya. It led to the deposition of Prime Minister Leabua Jonathan, who held the office since 1965 and assumed dictatorial powers in the 1970 coup d''état, after the general election was annulled.', 1986, 1, 15, NULL, NULL, NULL, 'day', '15 January 1986', 43, 'https://en.wikipedia.org/wiki/1986_Lesotho_coup_d''%C3%A9tat'),
